const binaryKeys = Object.keys($binary || {});

// Generate Unique Correlation Request ID: KRISHI-YYYYMMDD-XXXX
const now = new Date();
const dateStr = now.toISOString().slice(0,10).replace(/-/g, '');
const randStr = Math.random().toString(36).substring(2, 6).toUpperCase();
const requestId = `KRISHI-${dateStr}-${randStr}`;

// Check scan_type
const rawScanType = String($json.body?.scan_type || $json.query?.scan_type || '').toLowerCase().trim();
const isPesticideScan = (rawScanType === 'pesticide');

// Language extraction
const langMap = {
  'en': 'English',
  'kn': 'Kannada',
  'ta': 'Tamil',
  'te': 'Telugu',
  'ml': 'Malayalam',
  'hi': 'Hindi'
};
const rawLang = String($json.body?.language || $json.query?.language || 'en').toLowerCase().trim();
const languageCode = langMap[rawLang] ? rawLang : (Object.keys(langMap).find(k => langMap[k].toLowerCase() === rawLang) || 'en');
const requestedLanguage = langMap[languageCode] || 'English';

// =========================================================================
// BRANCH 1: PESTICIDE LABEL SCANNER
// =========================================================================
if (isPesticideScan) {
  if (binaryKeys.length === 0) {
    return [{
      json: {
        requestId: requestId,
        isValid: false,
        scan_type: 'pesticide',
        errorCode: 'NO_IMAGE_PROVIDED',
        message: 'No pesticide label photo was provided. Please provide at least one photo of the pesticide bottle or sachet.'
      }
    }];
  }

  const imagesList = [];
  for (let i = 0; i < Math.min(binaryKeys.length, 3); i++) {
    const key = binaryKeys[i];
    const bin = $binary[key];
    const mimeType = bin.mimeType || 'image/jpeg';
    if (!mimeType.startsWith('image/')) {
      return [{
        json: {
          requestId: requestId,
          isValid: false,
          scan_type: 'pesticide',
          errorCode: 'INVALID_MIME_TYPE',
          message: `Invalid file format ${mimeType} for pesticide label.`
        }
      }];
    }
    let base64Data = '';
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, key);
      base64Data = buffer.toString('base64');
    } catch (e) {
      base64Data = bin.data || '';
    }
    imagesList.push({
      mimeType: mimeType,
      data: base64Data,
      fileName: bin.fileName || `pesticide_${i+1}.jpg`
    });
  }

  const rawCrop = String($json.body?.crop || $json.query?.crop || '').toLowerCase().trim();

  const promptText = `Expert Agricultural Chemical & Crop Medicine Verification AI for Indian Agriculture.
Analyze the uploaded photo(s) of the pesticide/fungicide/insecticide/herbicide/crop medicine container or packet.

CASE CONTEXT:
- Images Provided: ${imagesList.length}
${rawCrop ? `- Farmer Selected Crop for Compatibility Check: "${rawCrop}"\n` : ''}- Target Response Language: ${requestedLanguage} (Language Code: ${languageCode})

CRITICAL VERIFICATION RULES:
1. STRICT ZERO-HALLUCINATION & EVIDENCE CHECK:
- Carefully inspect visible container, printed label, text, trademarks, and graphics.
- If the image is NOT an agricultural chemical or crop medicine package (for example: a leaf photo, field, animal, human, fertilizer without pesticide active ingredient, household item, or random object):
  * Set: "identified": false, "confidence": 0.10, "unidentified_reason": "NOT_A_PESTICIDE"
  * In "user_message" (${requestedLanguage}): State clearly: "This photo does not appear to be an agricultural pesticide or crop medicine package. Please photograph a clear pesticide bottle, sachet, or box label."
- If the image IS an agricultural chemical container, BUT the text is too blurry, out of focus, glare-obscured, cut off, or illegible to reliably confirm the product name or active ingredient:
  * Set: "identified": false, "confidence": 0.25, "unidentified_reason": "UNREADABLE_OR_BLURRY"
  * In "user_message" (${requestedLanguage}): State clearly: "Product could not be identified confidently. Please take a clearer picture of the front or back label, ensure the active ingredient section is visible, and avoid glare or shadow."
- If the image IS clearly readable and depicts a genuine agricultural chemical product:
  * Set: "identified": true, "confidence": between 0.70 and 0.99
  * Extract:
    - "product_name": Commercial brand name (e.g. "Coragen", "Contaf", "Saaf", "Actara", "Baan", "Blitox", etc.)
    - "active_ingredient": Generic chemical active ingredient with concentration (e.g. "Chlorantraniliprole 18.5% SC", "Hexaconazole 5% SC", "Mancozeb 75% WP", etc.)
    - "formulation": Formulation code and description (e.g. "SC (Suspension Concentrate)", "WP (Wettable Powder)", "EC (Emulsifiable Concentrate)", "WG (Water Dispersible Granules)")
    - "category": "INSECTICIDE" | "FUNGICIDE" | "HERBICIDE" | "BIO-PESTICIDE" | "ACARICIDE" | "PLANT GROWTH REGULATOR"
    - "manufacturer": Visible manufacturer / company name if visible or known
    - "cibrc_registered": true or false
    - "is_banned": true if banned in India (e.g. Endosulfan, Monocrotophos on vegetables), false otherwise
    - "what_it_is": Clear, simple farmer-friendly explanation of what this medicine is in ${requestedLanguage}.
    - "general_use": What pests, diseases, or weeds it controls in ${requestedLanguage}.
    - "target_pests": Array of key target pests/diseases controlled (in ${requestedLanguage}).
    - "suitable_crops": Array of approved/suitable crops for this chemical.
    - "why_farmers_use_it": Explanation of why farmers choose this medicine (mode of action, quick knockdown, rainfastness, broad-spectrum control) in ${requestedLanguage}.
    - "safety_guidance": Array of 3-5 vital safety instructions (wear gloves and face mask, do not spray against wind, safe storage away from children and feed, pre-harvest safety interval, proper container disposal) in ${requestedLanguage}.
    - "dosage_notice": "Always check the printed package label or consult local agriculture officer (RSK / KVK) for exact dosage according to crop growth stage and sprayer water volume. Never exceed recommended concentration." DO NOT invent unverified dosages.
    - "crop_compatibility": ${rawCrop ? `Check whether this chemical is registered/suitable for "${rawCrop}". Return an object: {"is_suitable": boolean, "note": "Clear explanation in ${requestedLanguage} whether this chemical is verified for ${rawCrop} or warning if unverified/unsafe."}` : 'null'}
    - "user_message": Friendly, clear summary for the farmer in ${requestedLanguage}.

MANDATORY OUTPUT REQUIREMENT:
Return ONLY valid JSON matching this schema:
{
  "scan_type": "pesticide",
  "identified": true,
  "confidence": 0.95,
  "unidentified_reason": null,
  "product_name": "Coragen",
  "active_ingredient": "Chlorantraniliprole 18.5% SC",
  "formulation": "SC (Suspension Concentrate)",
  "category": "INSECTICIDE",
  "manufacturer": "FMC / DuPont",
  "cibrc_registered": true,
  "is_banned": false,
  "what_it_is": "...",
  "general_use": "...",
  "target_pests": ["..."],
  "suitable_crops": ["..."],
  "why_farmers_use_it": "...",
  "safety_guidance": ["..."],
  "dosage_notice": "Always check the printed package label or consult local agriculture officer for exact dosage.",
  "crop_compatibility": ${rawCrop ? '{"is_suitable": true, "note": "..."}' : 'null'},
  "user_message": "..."
}`;

  const imageParts = imagesList.map(img => ({
    inlineData: {
      mimeType: img.mimeType || 'image/jpeg',
      data: img.data
    }
  }));

  const geminiPayload = {
    contents: [
      {
        parts: [
          { text: promptText },
          ...imageParts
        ]
      }
    ],
    generationConfig: {
      responseMimeType: 'application/json',
      temperature: 0.0,
      seed: 42
    }
  };

  return [{
    json: {
      requestId: requestId,
      isValid: true,
      scan_type: 'pesticide',
      crop: rawCrop,
      imageCount: imagesList.length,
      images: imagesList,
      language: languageCode,
      requestedLanguage: requestedLanguage,
      geminiPayload: geminiPayload,
      startedAt: Date.now()
    }
  }];
}

