const rawCrop = String($json.body?.crop || $json.query?.crop || '').toLowerCase().trim();
const normalizedCrop = rawCrop.replace(/[\s-]+/g, '_');
let matchedCropId = null;

if (TARGET_75_CROPS.includes(normalizedCrop)) {
  matchedCropId = normalizedCrop;
} else if (cropAliases[normalizedCrop]) {
  matchedCropId = cropAliases[normalizedCrop];
} else {
  for (const crop of TARGET_75_CROPS) {
    if (normalizedCrop.includes(crop) || crop.includes(normalizedCrop)) {
      matchedCropId = crop;
      break;
    }
  }
}

if (!matchedCropId) {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'UNSUPPORTED_CROP',
      message: `Crop '${rawCrop}' is not currently supported in the 75-Crop Online AI matrix.`,
      supported_crop_count: TARGET_75_CROPS.length
    }
  }];
}

if (binaryKeys.length === 0) {
  return [{
    json: {
      requestId: requestId,
      isValid: false,
      errorCode: 'NO_IMAGE_PROVIDED',
      message: 'No crop leaf images were provided. Please upload at least 1 image.'
    }
  }];
}

