    symptoms: symptoms,
    language: languageCode,
    requestedLanguage: requestedLanguage,
    latitude: latitude,
    longitude: longitude,
    state: state,
    geminiPayload: geminiPayload,
    startedAt: Date.now()
  }
}];

const res = $json;

try {
  if (res.error || !res.candidates || !res.candidates[0]?.content?.parts?.[0]?.text) {
    return [{ json: { is_usable: false, error_reason: 'HTTP_OR_EMPTY_RESPONSE', model_attempted: 'Gemini 3.5 Flash Lite' } }];
  }

  const rawText = res.candidates[0].content.parts[0].text;
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  if (!cleaned || cleaned.length < 10) {
    return [{ json: { is_usable: false, error_reason: 'EMPTY_CONTENT', model_attempted: 'Gemini 3.5 Flash Lite' } }];
  }

  const parsed = JSON.parse(cleaned);

  // Check if this is a pesticide scan result
  if (parsed.scan_type === 'pesticide' || parsed.product_name !== undefined || parsed.identified !== undefined) {
    parsed.scan_type = 'pesticide';
    if (parsed.identified === undefined) {
      parsed.identified = false;
    }
    parsed.confidence = (parsed.confidence !== undefined && !isNaN(Number(parsed.confidence))) ? Number(parsed.confidence) : (parsed.identified ? 0.85 : 0.20);
    parsed.target_pests = Array.isArray(parsed.target_pests) ? parsed.target_pests : (parsed.target_pests ? [String(parsed.target_pests)] : []);
    parsed.suitable_crops = Array.isArray(parsed.suitable_crops) ? parsed.suitable_crops : (parsed.suitable_crops ? [String(parsed.suitable_crops)] : []);
    parsed.safety_guidance = Array.isArray(parsed.safety_guidance) ? parsed.safety_guidance : (parsed.safety_guidance ? [String(parsed.safety_guidance)] : []);
    return [{ json: { is_usable: true, model_used: 'Gemini 3.5 Flash Lite', parsed_data: parsed } }];
  }

  // Strict Schema Validation for Crop Disease
  if (!parsed.crop || typeof parsed.crop !== 'string') {
    return [{ json: { is_usable: false, error_reason: 'MISSING_CROP_FIELD', model_attempted: 'Gemini 3.5 Flash Lite' } }];
  }

  if (!parsed.health_status || typeof parsed.health_status !== 'string') {
    return [{ json: { is_usable: false, error_reason: 'MISSING_HEALTH_STATUS', model_attempted: 'Gemini 3.5 Flash Lite' } }];
  }

  if (parsed.confidence === undefined || parsed.confidence === null || isNaN(Number(parsed.confidence))) {
    return [{ json: { is_usable: false, error_reason: 'INVALID_CONFIDENCE_FIELD', model_attempted: 'Gemini 3.5 Flash Lite' } }];
  }

  const confNum = Number(parsed.confidence);
  if (confNum < 0 || confNum > 1) {
    return [{ json: { is_usable: false, error_reason: 'CONFIDENCE_OUT_OF_BOUNDS', model_attempted: 'Gemini 3.5 Flash Lite' } }];
  }

  // Ensure arrays
  parsed.symptoms = Array.isArray(parsed.symptoms) ? parsed.symptoms : (parsed.symptoms ? [String(parsed.symptoms)] : []);
  parsed.recommendations = Array.isArray(parsed.recommendations) ? parsed.recommendations : (parsed.recommendations ? [String(parsed.recommendations)] : []);
  parsed.prevention = Array.isArray(parsed.prevention) ? parsed.prevention : (parsed.prevention ? [String(parsed.prevention)] : []);

  return [{ json: { is_usable: true, model_used: 'Gemini 3.5 Flash Lite', parsed_data: parsed } }];
} catch (e) {
  return [{ json: { is_usable: false, error_reason: 'INVALID_JSON_SYNTAX', details: e.message, model_attempted: 'Gemini 3.5 Flash Lite' } }];
}

